CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"7b955cb1-9c1e-593e-89a6-c27b2fce0662","source_id":"1389","name_en":"posterior tibialis stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0638\u0646\u0628\u0648\u0628 \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["posterior tibialis stretch"],"muscle":"calves","equipment":"rope","aliases":["posterior tibialis stretch"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you.\nLoop the rope around the ball of your foot and hold the ends of the rope with your hands.\nGently pull the rope towards you, flexing your foot and stretching your calf muscles.\nHold the stretch for 20-30 seconds.\nRelease the tension on the rope and relax your foot.\nRepeat the stretch on the other leg.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u062d\u0628\u0644 \u062d\u0648\u0644 \u0643\u0631\u0629 \u0642\u062f\u0645\u0643 \u0648\u0623\u0645\u0633\u0643 \u0637\u0631\u0641\u064a \u0627\u0644\u062d\u0628\u0644 \u0628\u064a\u062f\u064a\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0646\u062d\u0648\u0643 \u0628\u0644\u0637\u0641\u060c \u0645\u0639 \u062b\u0646\u064a \u0642\u062f\u0645\u0643 \u0648\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0633\u0627\u0642.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0627\u0644\u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0627\u0644\u062d\u0628\u0644 \u0648\u0623\u0631\u062e\u0650 \u0642\u062f\u0645\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1389","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1389-DEEqoI2.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1389-DEEqoI2.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"74328c01-c8bc-58fb-8725-79993e91525b","source_id":"3119","name_en":"potty squat","name_ar":"\u0642\u0639\u0627\u062f\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621","match_names":["potty squat"],"muscle":"core","equipment":"bodyweight","aliases":["potty squat"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, toes pointing slightly outward.\nLower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.\nKeep your chest up and your back straight throughout the movement.\nLower yourself until your thighs are parallel to the ground or as low as you can comfortably go.\nPause for a moment at the bottom, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u062a\u0634\u064a\u0631 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0627\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636 \u0623\u0648 \u0645\u0646\u062e\u0641\u0636\u064b\u0627 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3119","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["quadriceps","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3119-75Bgtjy.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3119-75Bgtjy.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ba1f0641-cc14-5dfc-8b3a-99013d1b5197","source_id":"3132","name_en":"potty squat with support","name_ar":"\u0642\u0639\u0627\u062f\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0645\u0639 \u0627\u0644\u062f\u0639\u0645","match_names":["potty squat with support"],"muscle":"glutes","equipment":"bodyweight","aliases":["potty squat with support"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, toes pointing slightly outward.\nHold onto a stable support, such as a chair or wall, for balance.\nLower your body down into a squat position by bending your knees and pushing your hips back.\nKeep your chest up and your back straight throughout the movement.\nPause for a moment at the bottom, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u062a\u0634\u064a\u0631 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062a\u0645\u0633\u0643 \u0628\u062f\u0639\u0627\u0645\u0629 \u062b\u0627\u0628\u062a\u0629\u060c \u0645\u062b\u0644 \u0627\u0644\u0643\u0631\u0633\u064a \u0623\u0648 \u0627\u0644\u062d\u0627\u0626\u0637\u060c \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3132","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3132-b63ZzGe.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3132-b63ZzGe.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b0f53133-8574-57e1-87b3-1a5ec3e83b9f","source_id":"0648","name_en":"power clean","name_ar":"\u0627\u0644\u0637\u0627\u0642\u0629 \u0646\u0638\u064a\u0641\u0629","match_names":["power clean"],"muscle":"hamstrings","equipment":"barbell","aliases":["power clean"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start with the barbell on the ground in front of you, with your feet shoulder-width apart.\nBend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.\nKeep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.\nAs the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.\nAs the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.\nStand up with the barbell, fully extending your hips and knees.\nLower the barbell back down to the starting position, keeping control of the weight throughout the movement.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0623\u062b\u0646\u0627\u0621 \u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646.\n\u0639\u0646\u062f\u0645\u0627 \u064a\u0635\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0645\u0646\u062a\u0635\u0641 \u0641\u062e\u0630\u0643\u060c \u0627\u0633\u062d\u0628\u0647 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0645\u0639 \u0647\u0632 \u0643\u062a\u0641\u064a\u0643 \u0648\u0633\u062d\u0628 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0639\u0646\u062f\u0645\u0627 \u064a\u0635\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0646\u0642\u0637\u0629 \u0644\u0647\u060c \u0627\u0646\u0632\u0644 \u062a\u062d\u062a\u0647 \u0628\u0633\u0631\u0639\u0629\u060c \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u0648\u0644\u0647 \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0643\u062a\u0641\u064a\u0643 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0623\u0645\u0627\u0645\u064a.\n\u0642\u0641 \u0645\u0639 \u0627\u0644\u062d\u062f\u064a\u062f\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0648\u0632\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0648","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes","quadriceps","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0648-SiWCcTN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0648-SiWCcTN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"27f47262-a8e3-5ecf-88f7-bd6eb77da440","source_id":"3665","name_en":"power point plank","name_ar":"\u0644\u0648\u062d \u0628\u0627\u0648\u0631 \u0628\u0648\u064a\u0646\u062a","match_names":["power point plank"],"muscle":"core","equipment":"bodyweight","aliases":["power point plank"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.\nEngage your core and squeeze your glutes to maintain a stable position.\nLower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.\nHold this position for the desired amount of time, keeping your core and glutes engaged.\nTo return to the starting position, push through your forearms and lift your body back up into a high plank position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u064a\u0643 \u0648\u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0623\u062e\u0645\u0635 \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u0631.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u064a\u0643\u060c \u0630\u0631\u0627\u0639\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0643\u0644 \u0645\u0631\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0623\u062e\u0645\u0635 \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u0634\u063a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u0635\u0628 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0645\u0646 \u0627\u0644\u0648\u0642\u062a\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u062c\u0630\u0639 \u0648\u0627\u0644\u0623\u0631\u062f\u0627\u0641 \u0645\u0646\u0634\u063a\u0644\u0629.\n\u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0627\u062f\u0641\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0648\u0627\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0639\u0627\u0644\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3665","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","triceps","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3665-hCjGsRQ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3665-hCjGsRQ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"19ad6636-5740-5ea2-8e2b-bfb642d77915","source_id":"3203","name_en":"prisoner half sit-up (male)","name_ar":"\u0627\u0644\u0633\u062c\u064a\u0646 \u0646\