37\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3203","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3203-mgejmGP.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3203-mgejmGP.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7455b034-3dcb-5d83-8b45-5037c72c7a22","source_id":"1707","name_en":"prone twist on stability ball","name_ar":"\u062a\u0637\u0648\u0631 \u0639\u0631\u0636\u0629 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631","match_names":["prone twist on stability ball"],"muscle":"core","equipment":"stability_ball","aliases":["prone twist on stability ball"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.\nPlace your hands behind your head or cross them over your chest.\nEngage your core muscles and slowly lift your upper body off the ball, keeping your back straight.\nRotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.\nPause for a moment, then return to the starting position.\nRepeat the rotation to the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0644\u0645\u0633 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0623\u0648 \u0636\u0639\u0647\u0645\u0627 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0643\u0631\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0648\u062c\u0644\u0628 \u0643\u062a\u0641\u0643 \u0646\u062d\u0648 \u0627\u0644\u0648\u0631\u0643. \u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1707","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1707-1IG6gVF.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1707-1IG6gVF.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"53b27be5-e77e-5f5a-8986-8bbf5ab5f64a","source_id":"0651","name_en":"pull up (neutral grip)","name_ar":"\u0633\u062d\u0628 \u0645\u0627 \u064a\u0635\u0644 (\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629)","match_names":["pull up (neutral grip)"],"muscle":"back","equipment":"bodyweight","aliases":["pull up (neutral grip)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.\nEngage your core and squeeze your shoulder blades together.\nPull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.\nContinue pulling until your chin is above the bar.\nPause for a moment at the top, then slowly lower your body back down to the starting position with control.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629 (\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u062a\u0648\u0627\u062c\u0647 \u0628\u0639\u0636\u0647\u0627 \u0627\u0644\u0628\u0639\u0636) \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062f\u0641\u0639 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0648\u0631\u0643\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0623\u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0639 \u0627\u0644\u062a\u062d\u0643\u0645.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0651","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0651-0V2YQjW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0651-0V2YQjW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"153f33e2-8c1e-58f5-8396-5622e23e88dd","source_id":"0650","name_en":"pull-in (on stability ball)","name_ar":"\u0627\u0644\u0633\u062d\u0628 (\u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631)","match_names":["pull-in (on stability ball)"],"muscle":"core","equipment":"stability_ball","aliases":["pull-in (on stability ball)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\nPlace your hands on the sides of the stability ball for support.\nEngage your abs and slowly roll your hips forward, bringing your knees towards your chest.\nPause for a moment at the top of the movement, then slowly extend your legs back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062c\u0644\u0648\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0645\u0627 \u064a\u062c\u0639\u0644 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0650","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","sour