 to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636\u060c \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u064a\u0643.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u062b\u0645 \u0636\u0639\u0647 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u062f\u0641\u0639 \u0628\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0660","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0660-KZXAtKQ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0660-KZXAtKQ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"68477ae8-3d68-534b-883d-14851ddfc1a7","source_id":"0661","name_en":"push-up inside leg kick","name_ar":"\u062f\u0641\u0639 \u0645\u0627 \u064a\u0635\u0644 \u062f\u0627\u062e\u0644 \u0631\u0643\u0644\u0629 \u0627\u0644\u0633\u0627\u0642","match_names":["push-up inside leg kick"],"muscle":"glutes","equipment":"bodyweight","aliases":["push-up inside leg kick"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\nLower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.\nAs you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.\nLower your leg back down and repeat the push-up, then switch to the other leg.\nContinue alternating leg kicks with each push-up repetition.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062f\u0641\u0639 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0627\u0631\u0641\u0639 \u0625\u062d\u062f\u0649 \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0631\u0643\u0644\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0648\u0643\u0631\u0631 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0631\u0643\u0644\u0627\u062a \u0627\u0644\u0633\u0627\u0642 \u0645\u0639 \u0643\u0644 \u062a\u0643\u0631\u0627\u0631 \u0644\u0644\u0636\u063a\u0637.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0661","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0661-0br45wL.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0661-0br45wL.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ee95870a-a7df-5616-880e-30dc312c7b08","source_id":"0663","name_en":"push-up medicine ball","name_ar":"\u0643\u0631\u0629 \u0637\u0628\u064a\u0629 \u0644\u0644\u0636\u063a\u0637","match_names":["push-up medicine ball"],"muscle":"chest","equipment":"medicine_ball","aliases":["push-up medicine ball"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start in a high plank position with your hands on the medicine ball, shoulder-width apart.\nEngage your core and lower your body towards the ground by bending your elbows, keeping your back straight.\nPush through your palms to extend your arms and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0637\u0628\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u062f\u0641\u0639 \u0628\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0663","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0663-W8KAlkI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0663-W8KAlkI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"34207d18-9bc4-5213-8204-973ad3ba108e","source_id":"1467","name_en":"push-up on lower arms","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646","match_names":["push-up on lower arms"],"muscle":"triceps","equipment":"bodyweight","aliases":["push-up on lower arms"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a plank position with your forearms on the ground and elbows directly below your shoulders.\nEngage your core and keep your body in a straight line from head to toe.\nLower your chest towards the ground by bending your elbows, keeping them close to your body.\nPause for a moment at the bottom, then push yourself back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0645\u0639 \u0648\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0631\u0641\u0642\u064a\u0643 \u0623\u0633\u0641\u0644 \u0643\u062a\u0641\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0623\u062e\u0645\u0635 \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1467","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1467-4Jt8QsQ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1467-4Jt8QsQ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"44053230-2dbe-5c6f-825b-cf46d18b8004","source_id":"3145","name_en":"push-up plus","name_ar":"\u062f\u0641\u0639 \u0645\u0627 \u064a\u0635\u0644 \u0632\u0627\u0626\u062f","match_names":["push-up plus"],"muscle":"chest","equipment":"bodyweight","aliases":["push-up plus"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.\nLower your body towards the ground by bending your elbows, keeping them close to your sides.\nOnce your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.\nAt the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.\nPause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u064a\u0635\u0628\u062d \u0635\u062f\u0631\u0643 \u0641\u0648\u0642 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629\u064b\u060c \u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0644\u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062f\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3145","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3145-pvBMLHA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3145-pvBMLHA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"cf655d78-7d6f-5f45-850d-4631f7d94702","source_id":"0664","name_en":"push-up to side plank","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u062c\u0627\u0646\u0628\u064a","match_names":["push-up to side plank"],"muscle":"core","equipment":"bodyweight","aliases":["push-up to side plank"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands shoulder-width apart and your body in a straight line.\nLower your body towards the ground by bending your elbows, keeping your core engaged.\nPush back up to the starting position.\nShift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.\nHold the side plank position for a few seconds, then return to the starting position.\nRepeat the push-up and side plank on the opposite side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u062c\u0630\u0639\u0643 \u0645\u0634\u063a\u0648\u0644\u0627\u064b.\n\u0627\u062f\u0641\u0639 \u0644\u0644\u0623\u0639\u0644\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0627\u0646\u0642\u0644 \u0648\u0632\u0646\u0643 \u0625\u0644\u0649 \u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062c\u0627\u0646\u0628\u064a \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0648\u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062c\u0627\u0646\u0628\u064a \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0664","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","chest","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0664-KhHJ338.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0664-KhHJ338.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"20c0c06a-712a-5b6d-8f1f-393cb2ce5d66","source_id":"3533","name_en":"quads","name_ar":"\u0627\u0644\u0643\u0648\u0627\u062f","match_names":["quads"],"muscle":"quads","equipment":"bodyweight","aliases":["quads"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nLower your body by bending your knees and pushing your hips back as if sitting on a chair.\nKeep your chest up and your back straight.\nLower yourself until your thighs are parallel to the ground.\nPush through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u0627\u062f\u0641\u0639 \u0628\u0643\u0639\u0628\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3533","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3533-6YUfHPL.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3533-6YUfHPL.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b6880501-5f3b-5ea3-8e1b-82cb8b37c12a","source_id":"3201","name_en":"quarter sit-up","name_ar":"\u0631\u0628\u0639 \u0627\u0644\u062c\u0644\u0648\u0633","match_names":["quarter sit-up"],"muscle":"core","equipment":"bodyweight","aliases":["quarter sit-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0627\u0646\u062d\u0646\u064a \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0644 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3201","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3201-enxnJcM.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3201-enxnJcM.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"661a0ca6-b583-5dd6-8ea6-44454694d987","source_id":"3552","name_en":"quick feet v. 2","name_ar":"\u0623\u0642\u062f\u0627\u0645 \u0633\u0631\u064a\u0639\u0629 v.2","match_names":["quick feet v. 2"],"muscle":"quads","equipment":"bodyweight","aliases":["quick feet v. 2"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your arms by your sides.\nBegin by rapidly moving your feet up and down, as if you were running in place.\nKeep your movements quick and light, focusing on staying on the balls of your feet.\nContinue for the desired duration or number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u0628\u062f\u0623 \u0628\u062a\u062d\u0631\u064a\u0643 \u0642\u062f\u0645\u064a\u0643 \u0628\u0633\u0631\u0639\u0629 \u0644\u0623\u0639\u0644\u0649 \u0648\u0644\u0623\u0633\u0641\u0644\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u0631\u0643\u0636 \u0641\u064a \u0645\u0643\u0627\u0646\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062d\u0631\u0643\u0627\u062a\u0643 \u0633\u0631\u064a\u0639\u0629 \u0648\u062e\u0641\u064a\u0641\u0629\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0639\u0644\u0649 \u0627\u0644\u0628\u0642\u0627\u0621 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0623\u0648 \u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3552","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["calves","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3552-mweqJin.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3552-mweqJin.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"07f88218-c83e-5e91-8322-4e7287388f07","source_id":"0666","name_en":"raise single arm push-up","name_ar":"\u0631\u0641\u0639 \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0644\u0644\u0636\u063a\u0637","match_names":["raise single arm push-up"],"muscle":"chest","equipment":"bodyweight","aliases":["raise single arm push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\nExtend one arm straight out to the side, parallel to the ground.\nLower your body towards the ground by bending your elbows, keeping your back straight and core engaged.\nPush back up to the starting position, using your chest muscles to lift your body.\nRepeat with the other arm extended.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0645\u062f \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0634\u062f \u0627\u0644\u062c\u0630\u0639.\n\u0627\u062f\u0641\u0639 \u0644\u0644\u0623\u0639\u0644\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0666","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0666-13TpY4H.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0666-13TpY4H.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"42f891f2-4f06-5ed1-8bcd-4f1b32aaa47f","source_id":"0668","name_en":"rear decline bridge","name_ar":"\u062c\u0633\u0631 \u0627\u0644\u0627\u0646\u062d\u062f\u0627\u0631 \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["rear decline bridge"],"muscle":"glutes","equipment":"bodyweight","aliases":["rear decline bridge"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your back with your feet flat on the ground and your knees bent.\nPlace your arms by your sides with your palms facing down.\nEngage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.\nHold this position for a few seconds, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0636\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629\u060c \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u062d\u062a\u0649 \u064a\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0668","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0668-UpAlold.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0668-UpAlold.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"cdd0b925-7a72-5a6d-87b1-35cc5f0d9c34","source_id":"0669","name_en":"rear deltoid stretch","name_ar":"\u0627\u0645\u062a\u062f\u0627\u062f \u0627\u0644\u062f\u0627\u0644\u064a\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629","match_names":["rear deltoid stretch"],"muscle":"shoulders","equipment":"bodyweight","aliases":["rear deltoid stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand tall with your feet shoulder-width apart.\nExtend your right arm across your chest, placing your left hand on your right elbow.\nGently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.\nHold the stretch for 15-30 seconds, then release.\nRepeat on the other side.","steps_ar":"\u0642\u0641 \u0637\u0648\u064a\u0644\u064b\u0627 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643\u060c \u0648\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0639\u0644\u0649 \u0645\u0631\u0641\u0642\u0643 \u0627\u0644\u0623\u064a\u0645\u0646.\n\u0627\u0633\u062d\u0628 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0644\u0637\u0641 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643 \u0627\u0644\u0623\u064a\u0633\u0631\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0643\u062a\u0641\u0643 \u0627\u0644\u0623\u064a\u0645\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0669","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0669-xifhB5W.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0669-xifhB5W.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"93ae6574-247e-59c2-8b60-1ad1ca473a4e","source_id":"0670","name_en":"rear pull-up","name_ar":"\u0627\u0644\u0633\u062d\u0628 \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["rear pull-up"],"muscle":"back","equipment":"bodyweight","aliases":["rear pull-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\nHang from the bar with your arms fully extended and your body straight.\nEngage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.\nContinue pulling until your chin is above the bar.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0623\u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0670","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0670-CbFSYC1.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0670-CbFSYC1.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a5967a74-bd32-5b52-89a1-b5745b918d40","source_id":"1582","name_en":"reclining big toe pose with rope","name_ar":"\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0639\u0644\u0649 \u0625\u0635\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u0627\u0644\u0643\u0628\u064a\u0631 \u0628\u062d\u0628\u0644","match_names":["reclining big toe pose with rope"],"muscle":"hamstrings","equipment":"rope","aliases":["reclining big toe pose with rope"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie on your back with your legs extended and your arms by your sides.\nLoop the rope around the ball of your right foot and hold the ends of the rope with your hands.\nSlowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.\nHold the stretch for a few seconds, then slowly lower your leg back down to the starting position.\nRepeat with your left leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u062d\u0628\u0644 \u062d\u0648\u0644 \u0643\u0631\u0629 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0623\u0645\u0633\u0643 \u0637\u0631\u0641\u064a \u0627\u0644\u062d\u0628\u0644 \u0628\u064a\u062f\u064a\u0643.\n\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0631\u0643\u0628\u062a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0648\u0642\u062f\u0645\u0643 \u0645\u062b\u0646\u064a\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1582","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["calves","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1582-K5xgdvI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1582-K5xgdvI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"56925cbf-ecf4-5db7-8cec-5f0757e27d83","source_id":"3236","name_en":"resistance band hip thrusts on knees (female)","name_ar":"\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u064a\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 (\u0623\u0646\u062b\u0649)","match_names":["resistance band hip thrusts on knees (female)"],"muscle":"glutes","equipment":"resistance_band","aliases":["resistance band hip thrusts on knees (female)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by kneeling on the ground with your knees hip-width apart and your feet flexed.\nWrap the resistance band around your thighs, just above your knees.\nPlace your hands on your hips or extend them out in front of you for balance.\nEngage your glutes and core muscles.\nPush your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.\nHold the position for a moment, then slowly lower your knees back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0631\u0643\u0648\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643 \u0648\u062b\u0646\u064a \u0642\u062f\u0645\u064a\u0643.\n\u0644\u0641 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u062d\u0648\u0644 \u0641\u062e\u0630\u064a\u0643\u060c \u0641\u0648\u0642 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0648\u0631\u0643\u064a\u0643 \u0623\u0648 \u0645\u062f\u0647\u0645\u0627 \u0623\u0645\u0627\u0645\u0643 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0623\u0644\u0648\u064a\u0629 \u0648\u0627\u0644\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629.\n\u0627\u062f\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0623\u062b\u0646\u0627\u0621 \u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3236","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3236-Pjbc0Kt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3236-Pjbc0Kt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b34d0af0-8815-5807-8819-ba27fae07739","source_id":"3007","name_en":"resistance band leg extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0641\u0631\u0642\u0629 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629","match_names":["resistance band leg extension"],"muscle":"quads","equipment":"resistance_band","aliases":["resistance band leg extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the resistance band to a sturdy anchor point and secure it around your ankle.\nStand facing the anchor point with your feet shoulder-width apart.\nKeeping your core engaged and your upper body stable, extend your leg straight out in front of you.\nPause for a moment at the top, then slowly return your leg to the starting position.\nRepeat for the desired number of repetitions, then switch legs.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0628\u0646\u0642\u0637\u0629 \u062a\u062b\u0628\u064a\u062a \u0642\u0648\u064a\u0629 \u0648\u062b\u0628\u062a\u0647 \u062d\u0648\u0644 \u0643\u0627\u062d\u0644\u0643.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0642\u0644\u0628\u0643 \u0645\u0646\u0634\u063a\u0644\u064b\u0627 \u0648\u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u0623\u0645\u0627\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0639\u062f \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3007","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3007-Y1MsI1l.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3007-Y1MsI1l.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7b44db84-9482-5f15-8990-8360f69229d5","source_id":"3123","name_en":"resistance band seated biceps curl","name_ar":"\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u064a\u062c\u0644\u0633 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646","match_names":["resistance band seated biceps curl"],"muscle":"biceps","equipment":"resistance_band","aliases":["resistance band seated biceps curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a chair or bench with your back straight and feet flat on the ground.\nHold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.\nKeeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.\nPause for a moment at the top, squeezing your biceps.\nInhale and slowly lower the resistance band back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a \u0623\u0648 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0648\u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0645\u062a\u062c\u0647\u062a\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0645\u062f \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3123","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3123-XFc3vpY.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3123-XFc3vpY.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2f8d7ed2-2cd6-5ef4-80ed-e591bfaa6caa","source_id":"3124","name_en":"resistance band seated chest press","name_ar":"\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u064a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u0631","match_names":["resistance band seated chest press"],"muscle":"chest","equipment":"resistance_band","aliases":["resistance band seated chest press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a chair or bench with your back straight and feet flat on the ground.\nHold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.\nExtend your arms forward, pushing the resistance band away from your chest.\nPause for a moment at the end of the movement, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a \u0623\u0648 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u062b\u0646\u064a\u064a\u0646 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0627\u062f\u0641\u0639 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0627\u062a \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3124","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3124-4x5Okof.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3124-4x5Okof.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2e0bbc1a-eef3-5be6-8420-788f4debbf69","source_id":"3006","name_en":"resistance band seated hip abduction","name_ar":"\u0641\u0631\u0642\u0629 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u064a\u062c\u0644\u0633 \u0627\u062e\u062a\u0637\u0627\u0641 \u0627\u0644\u0648\u0631\u0643","match_names":["resistance band seated hip abduction"],"muscle":"abductors","equipment":"resistance_band","aliases":["resistance band seated hip abduction"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a chair or bench with your back straight and feet flat on the ground.\nWrap the resistance band around your thighs, just above your knees.\nPlace your hands on the sides of the chair or bench for support.\nEngage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.\nPause for a moment at the end of the movement, then slowly bring your knees back together.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a \u0623\u0648 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0644\u0641 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u062d\u0648\u0644 \u0641\u062e\u0630\u064a\u0643\u060c \u0641\u0648\u0642 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0643\u0631\u0633\u064a \u0623\u0648 \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u062e\u0627\u0637\u0641\u064a\u0646 (\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0641\u062e\u0630 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629) \u0648\u0627\u062f\u0641\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0636\u0645 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0639\u064b\u0627 \u0628\u0628\u0637\u0621.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3006","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abductors","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3006-0xDpB4L.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3006-0xDpB4L.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0fa1f3b8-b2d6-5f85-8e23-f48ddb924baa","source_id":"3122","name_en":"resistance band seated shoulder press","name_ar":"\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u064a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0643\u062a\u0641","match_names":["resistance band seated shoulder press"],"muscle":"shoulders","equipment":"resistance_band","aliases":["resistance band seated shoulder press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a chair or bench with your back straight and feet flat on the ground.\nHold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.\nPress the band overhead, extending your arms fully.\nPause for a moment at the top, then slowly lower the band back down to shoulder level.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a \u0623\u0648 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u062b\u0645 \u0627\u0631\u0641\u0639\u0647 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u0644\u0648\u064a\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3122","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3122-S93zLTG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3122-S93zLTG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b19b010c-ca36-58e7-88a2-6beee0a6ec3a","source_id":"3144","name_en":"resistance band seated straight back row","name_ar":"\u0641\u0631\u0642\u0629 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u062a\u062c\u0644\u0633 \u0641\u064a \u0627\u0644\u0635\u0641 \u0627\u0644\u062e\u0644\u0641\u064a \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645","match_names":["resistance band seated straight back row"],"muscle":"back","equipment":"resistance_band","aliases":["resistance band seated straight back row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on the floor with your legs extended and loop the resistance band around your feet.\nHold the ends of the resistance band with your hands, palms facing each other.\nKeep your back straight and lean slightly back, engaging your core.\nPull the resistance band towards your chest, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly release the tension and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0644\u0641 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u062d\u0648\u0644 \u0642\u062f\u0645\u064a\u0643.\n\u0623\u0645\u0633\u0643 \u0637\u0631\u0641\u064a \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0628\u064a\u062f\u064a\u0643\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0645\u0639 \u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643.\n\u0627\u0633\u062d\u0628 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u0648\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3144","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3144-Nu7jqFE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3144-Nu7jqFE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"22ed8e2c-7731-55fb-81b2-a23f01e4679d","source_id":"0872","name_en":"reverse crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0639\u0643\u0633\u064a\u0629","match_names":["reverse crunch"],"muscle":"core","equipment":"bodyweight","aliases":["reverse crunch"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your arms extended along your sides.\nBend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.\nContract your abs and curl your hips off the floor, bringing your knees towards your chest.\nPause for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0641\u062e\u0630\u064a\u0643 \u0645\u062a\u0639\u0627\u0645\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u062c\u0644\u0628 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0872","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0872-nCU1Ekp.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0872-nCU1Ekp.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b6704391-8933-5e7e-88b7-974b8935986b","source_id":"0672","name_en":"reverse dip","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0639\u0643\u0633\u064a","match_names":["reverse dip"],"muscle":"triceps","equipment":"bodyweight","aliases":["reverse dip"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Position yourself between two parallel bars with your arms fully extended and your body straight.\nLower your body by bending your elbows until your upper arms are parallel to the ground.\nPause for a moment, then push yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0646\u0641\u0633\u0643 \u0628\u064a\u0646 \u0642\u0636\u064a\u0628\u064a\u0646 \u0645\u062a\u0648\u0627\u0632\u064a\u064a\u0646 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0672","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0672-NZ5Qqkz.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0672-NZ5Qqkz.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"db5ec2aa-e761-5b37-890e-c32fde691d20","source_id":"0673","name_en":"reverse grip machine lat pulldown","name_ar":"\u0622\u0644\u0629 \u0642\u0628\u0636\u0629 \u0639\u0643\u0633\u064a\u0629 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0627\u0644\u0644\u0627\u062a","match_names":["reverse grip machine lat pulldown"],"muscle":"back","equipment":"machine","aliases":["reverse grip machine lat pulldown"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.\nGrasp the handles with an underhand grip, slightly wider than shoulder-width apart.\nSit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.\nPull the handles down towards your chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0636\u0639 \u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u062a\u062d\u062a \u0627\u0644\u0648\u0633\u0627\u062f\u0627\u062a \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u0628\u0627\u0639\u062f\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062c\u0644\u0633 \u0641\u064a \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0635\u062f\u0631\u0643 \u0644\u0644\u062e\u0627\u0631\u062c \u0648\u0643\u062a\u0641\u064a\u0643 \u0644\u0644\u062e\u0644\u0641\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0642\u0648\u0633 \u0628\u0633\u064a\u0637 \u0641\u064a \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0673","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0673-ecpY0rH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0673-ecpY0rH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8ee1d3a1-9eec-59e9-8cb0-0c90d153a0bb","source_id":"0674","name_en":"reverse grip pull-up","name_ar":"\u0633\u062d\u0628 \u0642\u0628\u0636\u0629 \u0639\u0643\u0633\u064a\u0629","match_names":["reverse grip pull-up"],"muscle":"back","equipment":"bodyweight","aliases":["reverse grip pull-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Grab the pull-up bar with an underhand grip, hands shoulder-width apart.\nHang from the bar with your arms fully extended and your body straight.\nEngage your back muscles and pull your body up towards the bar, leading with your chest.\nContinue pulling until your chin is above the bar.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0623\u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0674","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0674-YAk5dIw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0674-YAk5dIw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bb2df5a8-a87e-5d78-8eab-df38558536a8","source_id":"0675","name_en":"reverse hyper extension (on stability ball)","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0641\u0631\u0637 \u0639\u0643\u0633\u064a (\u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631)","match_names":["reverse hyper extension (on stability ball)"],"muscle":"glutes","equipment":"stability_ball","aliases":["reverse hyper extension (on stability ball)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.\nPlace your hands on the ground in front of you for stability.\nEngaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0648\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u062e\u0644\u0641\u0643 \u0645\u0628\u0627\u0634\u0631\u0629.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629\u060c \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0675","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0675-vM5YS2g.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0675-vM5YS2g.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"19834cfc-0989-571c-8ac3-c369a54c3512","source_id":"1423","name_en":"reverse hyper on flat bench","name_ar":"\u0641\u0631\u0637 \u0639\u0643\u0633\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d","match_names":["reverse hyper on flat bench"],"muscle":"glutes","equipment":"bodyweight","aliases":["reverse hyper on flat bench"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.\nHold onto the bench for stability.\nKeeping your legs straight, raise them up towards the ceiling as high as you can.\nSqueeze your glutes at the top of the movement.\nSlowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d \u0645\u0639 \u0648\u0636\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0641\u0629 \u0648\u0633\u0627\u0642\u064a\u0643 \u0645\u0639\u0644\u0642\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u0627\u0644\u0645\u0642\u0639\u062f \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631.\n\u062d\u0627\u0641\u0638\u064a \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0633\u0627\u0642\u064a\u0643\u060c \u0648\u0627\u0631\u0641\u0639\u064a\u0647\u0645\u0627 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1423","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1423-OrETs32.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1423-OrETs32.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3f6ddc97-c25b-5d52-894e-cbe3a6335716","source_id":"3663","name_en":"reverse plank with leg lift","name_ar":"\u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0639\u0643\u0633\u064a \u0645\u0639 \u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642","match_names":["reverse plank with leg lift"],"muscle":"core","equipment":"bodyweight","aliases":["reverse plank with leg lift"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.\nPress through your hands and lift your hips off the ground, coming into a reverse plank position.\nEngage your core and lift one leg off the ground, extending it straight up towards the ceiling.\nHold for a moment, then lower your leg back down.\nRepeat with the other leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643 \u0648\u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u062e\u0644\u0641\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0646\u062d\u0648 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0636\u063a\u0637 \u0645\u0646 \u062e\u0644\u0627\u0644 \u064a\u062f\u064a\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0639\u0643\u0633\u064a.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0625\u062d\u062f\u0649 \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0642\u0645 \u0628\u0645\u062f\u0647\u0627 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u0627\u0646\u062a\u0638\u0631 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0633\u0627\u0642\u0643 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3663","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["glutes","hamstrings","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3663-tFToB7l.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3663-tFToB7l.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"630e1b4d-ff8a-5e78-8d52-431e99290218","source_id":"0677","name_en":"ring dips","name_ar":"\u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636\u0627\u062a \u0627\u0644\u062f\u0627\u0626\u0631\u064a\u0629","match_names":["ring dips"],"muscle":"triceps","equipment":"bodyweight","aliases":["ring dips"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by hanging from the rings with your arms fully extended and your body straight.\nLower your body by bending your elbows until your shoulders are below your elbows.\nPush yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0627\u0644\u062d\u0644\u0642\u0627\u062a \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0643\u062a\u0641\u064a\u0643 \u062a\u062d\u062a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0677","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0677-ezTvXcr.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0677-ezTvXcr.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f9e245a3-4e96-58ce-8412-44a6d3beb95b","source_id":"2571","name_en":"rocking frog stretch","name_ar":"\u0627\u0645\u062a\u062f\u0627\u062f \u0627\u0644\u0636\u0641\u062f\u0639 \u0627\u0644\u0647\u0632\u0627\u0632","match_names":["rocking frog stretch"],"muscle":"glutes","equipment":"bodyweight","aliases":["rocking frog stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Start by kneeling on the ground with your knees hip-width apart.\nPlace your hands on the ground in front of you for support.\nSlowly lean forward, shifting your weight onto your hands and extending your legs behind you.\nKeep your back straight and engage your glutes as you push your hips back and up towards the ceiling.\nHold this position for a few seconds, feeling a stretch in your glutes.\nSlowly return to the starting position by bending your knees and lowering your hips back down.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0631\u0643\u0648\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0627\u0646\u062d\u0646\u064a \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0646\u0642\u0644 \u0648\u0632\u0646\u0643 \u0639\u0644\u0649 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u062e\u0644\u0641\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0623\u062b\u0646\u0627\u0621 \u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u062e\u0644\u0641 \u0648\u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629.\n\u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2571","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2571-2Dk4xQV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2571-2Dk4xQV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"706e20b2-c432-5c93-872d-5152ea606dc0","source_id":"0678","name_en":"rocky pull-up pulldown","name_ar":"\u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0627\u0644\u0635\u062e\u0631\u064a\u0629","match_names":["rocky pull-up pulldown"],"muscle":"back","equipment":"bodyweight","aliases":["rocky pull-up pulldown"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand in front of a pull-up bar with your feet shoulder-width apart.\nReach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.\nHang from the bar with your arms fully extended and your body straight.\nEngage your back muscles and pull your body up towards the bar, leading with your chest.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0623\u0645\u0627\u0645 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0623\u0639\u0631\u0636 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0678","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0678-cQ19bBP.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0678-cQ19bBP.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
